{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "keep",
  "supportive_card_ids": ["C03","C15","C17","C07","C13","C18","C27","C06","C08","C23","C24","C68","C69","C73"],
  "contradictory_card_ids": ["C16","C22","C26"],
  "prediction_basis_card_ids": ["C03","C15","C17","C07","C13","C18","C27","C06","C08","C23","C24"],
  "claims": [
    {
      "claim": "The query is a pyridine-sulfonylurea loop diuretic; the closest same-condition context is bumetanide, another loop diuretic with a sulfonamide-type acidic group, which had absolute oral bioavailability of 95% in patients with cirrhosis (1 mg oral vs IV, n=8), with a second record reporting 95-100%.",
      "card_ids": ["C03","C15","C17"]
    },
    {
      "claim": "Tolfenamic acid in cirrhosis showed absolute oral bioavailability of about 100% by AUC comparison after 100 mg p.o. vs i.v., with additional patient values of 91%, 113%, and 126%; isradipine in cirrhosis had systemic availability of 28-37%. All are above the 20% threshold.",
      "card_ids": ["C07","C13","C18","C27","C06","C08","C23","C24"]
    },
    {
      "claim": "The query physicochemical prior (neutral fraction 0, logD -0.84, TPSA 100) is not affirmative evidence of F<20%; ionized acidic loop diuretics such as bumetanide show high F in the same cirrhosis condition.",
      "card_ids": ["C03","C15","C07","C13"]
    },
    {
      "claim": "New L6 hepatic-clearance records are not direct F measurements for the query or cirrhosis. The tolbutamide CYP2C9 intrinsic-clearance values are very low (wild-type 2.71x10^-4 uL/mg/min; variants 0.26-2.66), and rat depletion CLint values are ~0.85-1.83 uL/min/mg; these do not indicate high hepatic first-pass extraction and are at most weakly supportive of low presystemic loss for a sulfonylurea scaffold.",
      "card_ids": ["C68","C69","C73","C65","C66","C67","C70","C71","C74","C75"]
    },
    {
      "claim": "Low-F records in the broader set (KNI-272 syrup 15.7%, IQG-607 in mice ~4%, slow-dissolving isoniazid tablet) involve different molecules, species, or formulations and cannot be quantitatively transferred to the query.",
      "card_ids": ["C16","C22","C26"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C64","C65","C66","C67","C68","C69","C70","C71","C72","C73","C74","C75"]
    }
  ],
  "evidence_gaps": [
    "No direct torasemide-in-cirrhosis bioavailability or AUC record is present in the supplied cards.",
    "L6 hepatic-clearance records are for tolbutamide, bupropion, and PYRUB-SO 21, not the query; no query-specific hepatic clearance or metabolic stability in cirrhosis is measured.",
    "Query-specific gut-wall efflux, intestinal metabolism, solubility, and first-pass extraction are not experimentally measured; the low prior is physicochemical only.",
    "Cirrhosis severity, dose, and formulation are unspecified; transfer from bumetanide, tolfenamic acid, and isradipine relies on structural and condition analogy.",
    "Low-F records (KNI-272 syrup, IQG-607 in mice, slow-dissolving isoniazid tablet) are non-transferable due to different molecules, species, or formulations."
  ],
  "decision_summary": "Predicted high (F >= 20%): all transferable cirrhosis-context records (bumetanide 95-100%, tolfenamic acid ~100%, isradipine 28-37%) are above threshold. L6 hepatic-clearance records are not direct F measurements and mostly show low intrinsic clearance for a sulfonylurea probe, so they do not indicate high first-pass loss and do not change the decision. The physicochemical low prior is not affirmative evidence of F<20%. Confidence remains high; revision kept."
}

